function showWordDetail(base,reading){const host=$('v13WordDetail');if(!host)return;let word=null;try{word=allVocab().find(w=>String(w.japanese||'').trim()===base)||allVocab().find(w=>reading&&String(w.hiragana||'').trim()===reading)||null}catch(_){}host.classList.remove('hidden');host.replaceChildren();const h=document.createElement('h4');h.textContent=base;host.append(h);const p=document.createElement('p');p.textContent=`Hiragana: ${reading||word?.hiragana||'belum tersedia'}`;host.append(p);if(word){const m=document.createElement('p');m.textContent=`Arti: ${word.meaning||'belum tersedia'}`;host.append(m);const pos=document.createElement('p');pos.className='tiny';pos.textContent=`Level: ${word.jlpt||'belum diklasifikasikan'} · Status: ${labelStatus(statusForWord(word))}`;host.append(pos);const actions=document.createElement('div');actions.className='v13-actions';const saveB=document.createElement('button');saveB.type='button';saveB.className='primary';saveB.textContent='Simpan ke daftar kosakata';saveB.addEventListener('click',()=>{if(!state.savedVocabulary.some(x=>x.id===word.id)){state.savedVocabulary.push({id:word.id,japanese:word.japanese,hiragana:word.hiragana,meaning:word.meaning,savedAt:new Date().toISOString()});persist()}const status=document.createElement('p');status.className='tiny';status.textContent='Disimpan secara lokal ke daftar kosakata Reader.';host.append(status);updateMetrics();renderSavedVocabulary()});const study=document.createElement('button');study.type='button';study.textContent='Latih di flashcard';study.addEventListener('click',()=>openWordInFlashcards(word));actions.append(saveB,study);host.append(actions)}else{const m=document.createElement('p');m.textContent='Kata ini belum ditemukan dalam kamus flashcard lokal. Pembacaan di atas berasal dari anotasi bacaan; artinya belum ditebak.';host.append(m);const actions=document.createElement('div');actions.className='v13-actions';const saveB=document.createElement('button');saveB.type='button';saveB.textContent='Simpan sebagai kata perlu dilengkapi';saveB.addEventListener('click',()=>{if(!state.capturedWords.some(x=>x.japanese===base&&x.hiragana===reading))state.capturedWords.push({japanese:base,hiragana:reading||'',meaning:'',status:'needs_review',capturedAt:new Date().toISOString()});persist();const status=document.createElement('p');status.className='tiny';status.textContent='Disimpan sebagai tangkapan Reader; lengkapi artinya sebelum menjadikannya kartu belajar.';host.append(status);updateMetrics();renderSavedVocabulary()});actions.append(saveB);host.append(actions)}}
function renderSavedVocabulary(){const host=$('v13SavedVocabularyList');if(!host)return;host.replaceChildren();if(!state.savedVocabulary.length&&!state.capturedWords.length){host.textContent='Belum ada kosakata yang disimpan dari Reader. Ketuk kata berfurigana untuk menyimpannya.';return}for(const x of state.savedVocabulary){const w=allVocab().find(y=>y.id===x.id)||x;const row=document.createElement('div');row.className='v13-word-row';const main=document.createElement('div');const strong=document.createElement('strong');strong.textContent=x.japanese||w.japanese||'';const small=document.createElement('div');small.className='tiny';small.textContent=`${x.hiragana||w.hiragana||'—'} · ${x.meaning||w.meaning||'—'}`;main.append(strong,small);const b=document.createElement('button');b.type='button';b.textContent='Latih';b.addEventListener('click',()=>openWordInFlashcards(w));row.append(main,b);host.append(row)}for(const x of state.capturedWords){const row=document.createElement('div');row.className='v13-word-row';const main=document.createElement('div');const strong=document.createElement('strong');strong.textContent=x.japanese;const small=document.createElement('div');small.className='tiny';small.textContent=`${x.hiragana||'bacaan belum tersedia'} · ${x.meaning||'arti perlu dilengkapi'}`;main.append(strong,small);row.append(main);host.append(row)}}
