function speakV13(text,rate){const target=String(text||'').trim();const status=$('v13VoiceStatus');if(!target){if(status)status.textContent='Masukkan teks Jepang sebelum memutar audio.';return false}if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){if(status)status.textContent='Speech synthesis tidak tersedia di browser/perangkat ini. Fitur reading dan flashcard tetap dapat digunakan.';return false}try{const voices=window.speechSynthesis.getVoices?.()||[];const selected=$('v13VoiceSelect')?.value||state.audioVoice||'';let voice=voices.find(v=>v.name===selected)||null;if(!voice)voice=voices.find(v=>/^ja(-|$)/i.test(v.lang))||voices.find(v=>/japanese|日本語/i.test(v.name))||null;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(target);u.lang='ja-JP';u.rate=Math.max(.55,Math.min(1.35,Number(rate??$('v13AudioRate')?.value??state.audioRate??.85)));if(voice)u.voice=voice;u.onstart=()=>{if(status)status.textContent=`Audio berjalan. Voice: ${voice?`${voice.name} (${voice.lang})`:'default browser'}. API tidak dapat memastikan apakah voice membutuhkan jaringan.`};u.onerror=e=>{if(status)status.textContent=`Audio gagal diputar: ${e.error||'error browser'}. Periksa voice Jepang di pengaturan perangkat.`};u.onend=()=>{};window.speechSynthesis.speak(u);return true}catch(e){if(status)status.textContent='Audio gagal: '+(e.message||String(e));return false}}
function refreshVoices(){const select=$('v13VoiceSelect');if(!select)return;const rateSelect=$('v13AudioRate');if(rateSelect){const allowed=[...rateSelect.options].some(o=>Number(o.value)===Number(state.audioRate));rateSelect.value=allowed?String(state.audioRate):'0.8';state.audioRate=Number(rateSelect.value)}const previous=state.audioVoice||select.value;const voices=('speechSynthesis'in window)?(speechSynthesis.getVoices?.()||[]):[];select.replaceChildren();const opt=document.createElement('option');opt.value='';opt.textContent='Otomatis / default browser';select.append(opt);const ja=voices.filter(v=>/^ja(-|$)/i.test(v.lang)||/japanese|日本語/i.test(v.name));for(const v of ja){const o=document.createElement('option');o.value=v.name;o.textContent=`${v.name} (${v.lang})`;select.append(o)}if([...select.options].some(o=>o.value===previous))select.value=previous;else select.value='';state.audioAvailable=!!('speechSynthesis'in window&&'SpeechSynthesisUtterance'in window);state.japaneseVoiceCount=ja.length;persist();const status=$('v13VoiceStatus');if(status){if(!state.audioAvailable)status.textContent='Speech synthesis tidak tersedia di lingkungan ini. Fitur teks tetap berfungsi.';else if(!ja.length)status.textContent='Speech synthesis tersedia, tetapi voice Jepang belum terdeteksi. Pasang voice Jepang di pengaturan Text-to-Speech perangkat bila tersedia.';else status.textContent=`Speech synthesis tersedia dengan ${ja.length} voice Jepang. Metadata browser tidak membuktikan voice sepenuhnya offline; uji dengan jaringan dimatikan.`}}
function rand(a){return a[Math.floor(Math.random()*a.length)]}
let listeningItem=null,listeningChoices=[];
function startListeningQuiz(){const all=allVocab().filter(w=>w&&w.japanese&&w.meaning&&w.hiragana);const leveled=all.filter(w=>w.jlpt===targetLevel());const words=leveled.length>=4?leveled:all;if(words.length<4){$('v13ListenQuizFeedback').textContent='Dataset belum memiliki empat kosakata yang valid untuk membuat pilihan.';return}listeningItem=rand(words);const pool=words.filter(w=>w.id!==listeningItem.id&&w.meaning!==listeningItem.meaning);const wrong=[];while(pool.length&&wrong.length<3){const x=pool.splice(Math.floor(Math.random()*pool.length),1)[0];if(!wrong.some(y=>y.meaning===x.meaning))wrong.push(x)}if(wrong.length<3){$('v13ListenQuizFeedback').textContent='Pilihan jawaban unik belum cukup.';return}listeningChoices=[listeningItem,...wrong].sort(()=>Math.random()-.5);$('v13ListenQuizPrompt').textContent='Dengarkan kata Jepang lalu pilih artinya.';$('v13ListenQuizPlay').disabled=false;$('v13ListenQuizFeedback').textContent='Audio sudah disiapkan. Pilihan arti tersedia di bawah.';const host=$('v13ListenQuizChoices');host.replaceChildren();for(const w of listeningChoices){const b=document.createElement('button');b.type='button';b.textContent=w.meaning;b.addEventListener('click',()=>answerListeningQuiz(w,b));host.append(b)}speakV13(listeningItem.japanese,$('v13AudioRate')?.value||.85)}
function answerListeningQuiz(chosen,button){if(!listeningItem)return;const correct=chosen.id===listeningItem.id;state.listeningStats.attempts=Number(state.listeningStats.attempts||0)+1;if(correct)state.listeningStats.correct=Number(state.listeningStats.correct||0)+1;state.listeningStats.history=[...(state.listeningStats.history||[]),{at:new Date().toISOString(),wordId:listeningItem.id,correct}].slice(-300);persist();document.querySelectorAll('#v13ListenQuizChoices button').forEach(b=>{b.disabled=true;if(b.textContent===listeningItem.meaning)b.classList.add('correct')});if(!correct)button.classList.add('incorrect');$('v13ListenQuizPrompt').textContent=`${listeningItem.japanese}（${listeningItem.hiragana}）`; $('v13ListenQuizFeedback').textContent=(correct?'Benar. ':'Belum tepat. ')+`${listeningItem.japanese}（${listeningItem.hiragana}） berarti ${listeningItem.meaning}.`;updateMetrics();}
